-- Staging table: raw copy of coffee_import.csv (1,311 rows)
-- Used instead of the Table Data Import Wizard, which fails on non-ASCII characters on macOS.
SET NAMES utf8mb4;
USE CoffeeQuality;
DROP TABLE IF EXISTS raw_coffee;
CREATE TABLE raw_coffee (
  SampleID VARCHAR(255),
  Species VARCHAR(255),
  Owner VARCHAR(255),
  Country VARCHAR(255),
  FarmName VARCHAR(255),
  LotNumber VARCHAR(255),
  HarvestYear VARCHAR(255),
  AltitudeMean VARCHAR(255),
  Aroma VARCHAR(255),
  Flavor VARCHAR(255),
  Acidity VARCHAR(255),
  TotalCupPoints VARCHAR(255)
);


SELECT COUNT(*) AS rows_loaded FROM raw_coffee;   -- should be 1311
